function norm(value: string) {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

function scorePage(page: PdfPageIndex, adventure: Adventure, node: AdventureNode) {
  const haystack = norm([page.headings.join(" "), page.textPreview ?? ""].join(" "));
  const adventureWords = norm(adventure.title).split(" ").filter((word) => word.length > 3);
  const nodeWords = norm(`${node.label} ${node.description}`).split(" ").filter((word) => word.length > 3);
  let score = 0;
  for (const word of adventureWords) if (haystack.includes(word)) score += 4;
  for (const word of nodeWords) if (haystack.includes(word)) score += 2;
  score += page.detectedEntities.length > 0 ? 1 : 0;
  return score;
}

function confidence(score: number) {
  if (score >= 9) return "high" as const;
  if (score >= 5) return "medium" as const;
  return "low" as const;
}

function suggest(
  args: Omit<AutoPrepSuggestion, "id" | "privateDmData">,
): AutoPrepSuggestion {
  return {
    ...args,
    id: `${args.nodeId}_${String(args.fieldName)}_${args.pdfPageIndex}_${Math.random().toString(36).slice(2, 7)}`,
    privateDmData: true,
  };
}

