    const keyedAreas = best.page.detectedEntities.filter((entity) => entity.type === "keyedArea").map((entity) => entity.name).filter(Boolean) as string[];
    const checks = best.page.detectedEntities.filter((entity) => entity.type === "skillCheck");
    const saves = best.page.detectedEntities.filter((entity) => entity.type === "savingThrow");
    const monsters = best.page.detectedEntities.filter((entity) => entity.type === "monster").map((entity) => entity.name).filter(Boolean) as string[];
    const items = best.page.detectedEntities.filter((entity) => entity.type === "item" || entity.type === "treasure").map((entity) => entity.name).filter(Boolean) as string[];
