import pdfWorker from "pdfjs-dist/build/pdf.worker.mjs?url";
import { SOURCE_BOOKS, type SourceBookId } from "@/data/sourceBooks";
import { indexPdfPage, guessPrintedPage } from "./pdfIndexer";
import { savePdfIndex } from "./pdfStorage";
import type { ImportedPdfSource, PdfPageIndex } from "./pdfTypes";

pdfjsLib.GlobalWorkerOptions.workerSrc = pdfWorker;

async function sha256(file: File) {
  const hash = await crypto.subtle.digest("SHA-256", await file.arrayBuffer());
  return Array.from(new Uint8Array(hash)).map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

function idFromHash(hash: string) {
  return `pdf_${hash.slice(0, 16)}`;
}

async function pageText(page: { getTextContent: () => Promise<{ items: unknown[] }> }) {
  const content = await page.getTextContent();
  return content.items
    .map((item) => {
      if (typeof item === "object" && item && "str" in item) return String((item as { str: string }).str);
      return "";
    })
    .join(" ");
}

export async function importPdfFile(file: File, sourceId: SourceBookId, offset = 0): Promise<{ source: ImportedPdfSource; pages: PdfPageIndex[] }> {
  const fileHash = await sha256(file);
  const id = idFromHash(fileHash);
  const sourceBook = SOURCE_BOOKS.find((book) => book.id === sourceId)?.title ?? sourceId;
  const data = new Uint8Array(await file.arrayBuffer());
  const pdf = await pdfjsLib.getDocument({ data }).promise;
  const pages: PdfPageIndex[] = [];
  let detectedTitle = sourceBook;

  for (let pageNumber = 1; pageNumber <= pdf.numPages; pageNumber += 1) {
    const page = await pdf.getPage(pageNumber);
    const text = await pageText(page);
    if (pageNumber === 1 && text.trim()) detectedTitle = text.replace(/\s+/g, " ").slice(0, 90);
    pages.push(indexPdfPage({
      pdfId: id,
      pdfPageIndex: pageNumber,
      printedPageRef: guessPrintedPage(pageNumber, offset),
      text,
      sourceId,
    }));
  }

  const source: ImportedPdfSource = {
    id,
    sourceId,
    sourceBook,
    fileName: file.name,
    fileHash,
    importedAt: new Date().toISOString(),
    pageCount: pdf.numPages,
    detectedTitle,
    rawPdfStored: false,
    localOnly: true,
    enteredByUser: true,
    privateDmData: true,
    doNotCommit: true,
    pdfPageOffset: offset,
    lastIndexedAt: new Date().toISOString(),
  };
  await savePdfIndex(source, pages);
  return { source, pages };
}
