import type { DetectedEntity, PdfPageIndex } from "./pdfTypes";

const ABILITIES = "(Strength|Dexterity|Constitution|Intelligence|Wisdom|Charisma|STR|DEX|CON|INT|WIS|CHA)";
const SKILLS = "(Acrobatics|Animal Handling|Arcana|Athletics|Deception|History|Insight|Intimidation|Investigation|Medicine|Nature|Perception|Performance|Persuasion|Religion|Sleight of Hand|Stealth|Survival)";

const COMMON_MONSTERS = [
  "aboleth", "acolyte", "bandit", "beholder", "bugbear", "cultist", "dragon",
  "goblin", "kobold", "ooze", "skeleton", "slime", "specter", "swarm", "twig blight",
  "vampire", "wight", "wolf", "zombie",
];

const TREASURE_WORDS = ["treasure", "coins", "gold", "silver", "gem", "potion", "scroll", "wand", "ring", "armor", "weapon"];
const TRAP_WORDS = ["trap", "hazard", "poison", "pit", "glyph", "snare", "falling", "pressure plate"];

function titleCase(value: string) {
  return value.replace(/\w\S*/g, (part) => part[0].toUpperCase() + part.slice(1).toLowerCase());
}

function shortPreview(text: string) {
  return text.replace(/\s+/g, " ").trim().slice(0, 220);
}

function detectHeadings(lines: string[]) {
  return lines
    .map((line) => line.trim())
    .filter((line) => line.length >= 4 && line.length <= 80)
    .filter((line) => {
      const words = line.split(/\s+/);
      const capitalized = words.filter((word) => /^[A-Z0-9]/.test(word)).length;
      return capitalized / Math.max(words.length, 1) > 0.65;
    })
    .slice(0, 6);
}

function pushUnique(entities: DetectedEntity[], entity: DetectedEntity) {
  const key = `${entity.type}:${entity.name ?? entity.skill ?? entity.ability ?? ""}:${entity.dc ?? ""}`;
  const exists = entities.some((item) => `${item.type}:${item.name ?? item.skill ?? item.ability ?? ""}:${item.dc ?? ""}` === key);
  if (!exists) entities.push(entity);
}

export function indexPdfPage(args: {
  pdfId: string;
  pdfPageIndex: number;
  printedPageRef?: string;
  text: string;
  sourceId: SourceBookId;
}): PdfPageIndex {
  const text = args.text.replace(/\u0000/g, " ");
  const lines = text.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
  const headings = detectHeadings(lines);
  const entities: DetectedEntity[] = [];

  for (const heading of headings) {
    pushUnique(entities, { type: "section", name: heading, pageRef: args.printedPageRef, confidence: "medium", localOnly: true });
  }

  for (const match of text.matchAll(new RegExp(`DC\\s+(\\d{1,2})\\s+${ABILITIES}(?:\\s*\\((${SKILLS.replace(/[()]/g, "")})\\))?`, "gi"))) {
    const skill = match[3] ?? match[2];
    pushUnique(entities, {
      type: skill ? "skillCheck" : "savingThrow",
      ability: match[2],
      skill,
      dc: Number(match[1]),
      pageRef: args.printedPageRef,
      confidence: skill ? "high" : "medium",
      localOnly: true,
    });
  }

  for (const match of text.matchAll(new RegExp(`DC\\s+(\\d{1,2})\\s+${ABILITIES}\\s+saving throw`, "gi"))) {
    pushUnique(entities, {
      type: "savingThrow",
      ability: match[2],
      dc: Number(match[1]),
      pageRef: args.printedPageRef,
      confidence: "high",
      localOnly: true,
    });
  }

  for (const match of text.matchAll(/\b(?:Area|Room)\s+([A-Z]?\d+[A-Z]?)[.: -]+([^\n.]{3,80})/gi)) {
    pushUnique(entities, {
      type: "keyedArea",
      name: `${match[0]}`.slice(0, 90),
      pageRef: args.printedPageRef,
      confidence: "medium",
      localOnly: true,
    });
  }

  for (const monster of COMMON_MONSTERS) {
    if (new RegExp(`\\b${monster}\\b`, "i").test(text)) {
      pushUnique(entities, {
        type: "monster",
        name: titleCase(monster),
        pageRef: args.printedPageRef,
        confidence: "low",
        localOnly: true,
      });
    }
  }

  for (const word of TREASURE_WORDS) {
    if (new RegExp(`\\b${word}\\b`, "i").test(text)) {
      pushUnique(entities, { type: "treasure", name: titleCase(word), pageRef: args.printedPageRef, confidence: "low", localOnly: true });
    }
  }

  for (const word of TRAP_WORDS) {
    if (new RegExp(`\\b${word}\\b`, "i").test(text)) {
      pushUnique(entities, { type: word === "trap" ? "trap" : "hazard", name: titleCase(word), pageRef: args.printedPageRef, confidence: "low", localOnly: true });
    }
  }

  if (/read aloud|boxed text|when .* read/i.test(text)) {
    pushUnique(entities, {
      type: "boxedTextMarker",
      name: "Read official boxed text from sourcebook",
      pageRef: args.printedPageRef,
      confidence: "low",
      localOnly: true,
    });
  }

  return {
    pdfId: args.pdfId,
    pdfPageIndex: args.pdfPageIndex,
    printedPageRef: args.printedPageRef,
    headings,
    textPreview: shortPreview(text),
    detectedEntities: entities,
    localOnly: true,
    privateDmData: true,
  };
}

export function guessPrintedPage(pdfPageIndex: number, offset = 0) {
  return String(Math.max(1, pdfPageIndex + offset));
}
