const DB_NAME = "canon-table-engine-pdf";
const DB_VERSION = 1;
const SOURCES_STORE = "sources";
const PAGES_STORE = "pages";

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(SOURCES_STORE)) {
        db.createObjectStore(SOURCES_STORE, { keyPath: "id" });
      }
      if (!db.objectStoreNames.contains(PAGES_STORE)) {
        const store = db.createObjectStore(PAGES_STORE, { keyPath: ["pdfId", "pdfPageIndex"] });
        store.createIndex("pdfId", "pdfId", { unique: false });
      }
    };
    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result);
  });
}

function txDone(tx: IDBTransaction): Promise<void> {
  return new Promise((resolve, reject) => {
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
    tx.onabort = () => reject(tx.error);
  });
}

export async function savePdfIndex(source: ImportedPdfSource, pages: PdfPageIndex[]): Promise<void> {
  const db = await openDb();
  const tx = db.transaction([SOURCES_STORE, PAGES_STORE], "readwrite");
  tx.objectStore(SOURCES_STORE).put(source);
  const pagesStore = tx.objectStore(PAGES_STORE);
  for (const page of pages) pagesStore.put(page);
  await txDone(tx);
  db.close();
}

export async function listPdfSources(): Promise<ImportedPdfSource[]> {
  const db = await openDb();
  const tx = db.transaction(SOURCES_STORE, "readonly");
  const request = tx.objectStore(SOURCES_STORE).getAll();
  const rows = await new Promise<ImportedPdfSource[]>((resolve, reject) => {
    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result as ImportedPdfSource[]);
  });
  db.close();
  return rows.sort((a, b) => b.importedAt.localeCompare(a.importedAt));
}

export async function getPdfPages(pdfId: string): Promise<PdfPageIndex[]> {
  const db = await openDb();
  const tx = db.transaction(PAGES_STORE, "readonly");
  const index = tx.objectStore(PAGES_STORE).index("pdfId");
  const request = index.getAll(pdfId);
  const rows = await new Promise<PdfPageIndex[]>((resolve, reject) => {
    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result as PdfPageIndex[]);
  });
  db.close();
  return rows.sort((a, b) => a.pdfPageIndex - b.pdfPageIndex);
}

export async function deletePdfIndex(pdfId: string): Promise<void> {
  const pages = await getPdfPages(pdfId);
  const db = await openDb();
  const tx = db.transaction([SOURCES_STORE, PAGES_STORE], "readwrite");
  tx.objectStore(SOURCES_STORE).delete(pdfId);
  const pagesStore = tx.objectStore(PAGES_STORE);
  for (const page of pages) pagesStore.delete([pdfId, page.pdfPageIndex]);
  await txDone(tx);
  db.close();
}

export async function exportPdfIndex(pdfId: string): Promise<PdfIndexBundle | undefined> {
  const sources = await listPdfSources();
  const source = sources.find((item) => item.id === pdfId);
  if (!source) return undefined;
  return {
    schemaVersion: "pdf-index-v1",
    exportedAt: new Date().toISOString(),
    source,
    pages: await getPdfPages(pdfId),
  };
}

export async function importPdfIndex(bundle: PdfIndexBundle): Promise<void> {
  if (bundle.schemaVersion !== "pdf-index-v1") {
    throw new Error("Unsupported PDF index schema.");
  }
  await savePdfIndex(bundle.source, bundle.pages);
}
