  fileHash: string;
  importedAt: string;
  pageCount: number;
  detectedTitle: string;
  rawPdfStored: boolean;
  localOnly: true;
  enteredByUser: true;
  privateDmData: true;
  doNotCommit: true;
  pdfPageOffset?: number;
  lastIndexedAt?: string;
}

export type DetectedEntityType =
  | "adventureTitle"
  | "chapter"
  | "section"
  | "keyedArea"
  | "npc"
  | "monster"
  | "item"
  | "spell"
  | "trap"
  | "hazard"
  | "skillCheck"
  | "savingThrow"
  | "treasure"
  | "boxedTextMarker";

export interface DetectedEntity {
  type: DetectedEntityType;
  name?: string;
  ability?: string;
  skill?: string;
  dc?: number;
  damageFormula?: string;
  pageRef?: string;
  confidence: Confidence;
  localOnly: true;
}

export interface PdfPageIndex {
  pdfId: string;
  pdfPageIndex: number;
  printedPageRef?: string;
  headings: string[];
  textPreview?: string;
