import { savePdfIndex } from "./pdfStorage";

export function printedPageForPdfIndex(pdfPageIndex: number, offset = 0) {
  return String(Math.max(1, pdfPageIndex + offset));
}

export async function applyPageOffset(source: ImportedPdfSource, pages: PdfPageIndex[], offset: number) {
  const updatedSource = { ...source, pdfPageOffset: offset, lastIndexedAt: new Date().toISOString() };
  const updatedPages = pages.map((page) => ({
    ...page,
    printedPageRef: printedPageForPdfIndex(page.pdfPageIndex, offset),
    detectedEntities: page.detectedEntities.map((entity) => ({
      ...entity,
      pageRef: printedPageForPdfIndex(page.pdfPageIndex, offset),
    })),
  }));
  await savePdfIndex(updatedSource, updatedPages);
  return { source: updatedSource, pages: updatedPages };
}
