function defaultOverride(node: AdventureNode): NodeOverride {
  return {
    id: node.id,
    pageRef: "",
    chapter: "",
    keyedArea: "",
    sceneTitle: node.label,
    dmPrivateNote: "",
    playerSafeSummary: "",
    readAloud: "",
